def refund(balance, amount):
    if amount <= 0 or amount > balance:
        raise ValueError("invalid")
    return balance - amount

files.src/eligibility.py:
def eligible(order, inventory, mailer):
    allowed = inventory.available(order.sku) >= order.quantity
    if not allowed:
        mailer.send(order.owner, "insufficient stock")
    return allowed

