def summary(name, credit):
    result = {"name": name}
    if credit:
        result["credit"] = f"${credit}"
    return result

files.src/quota.py:
class Evaluator:
    def __init__(self):
        self.cache = {}
    def total(self, tenant, metric, load):
        key = (tenant, metric)
        if key not in self.cache:
            self.cache[key] = load(tenant, metric)
        return self.cache[key]

